+        playerId,
+        giverId: Number(quest.bindings?.giver || 0) | 0,
+        objective: "Find and defeat one of the healers in the Rootbound Grotto.",
+      });
+    });
+  }, { key: ROOTBOUND_HOOKS_KEY }));
+}
