+            actions: [
+              setVar("defeated", true),
+              emit("quest:advanced", (ctx) => ({
+                questId: ROOTBOUND_GROTTO_QUEST_ID,
+                playerId: ctx.bind.player,
+                giverId: ctx.bind.giver,
