    postCharacterCreated({
      playerName: classData?.name ?? "Hero",
      classId: classDef?.id ?? null,
      className: classDef?.name ?? null,
      seed: (world.seed >>> 0).toString(16),
      startDepth: _startDepth,
      timestamp: Date.now(),
