REGISTRY['divine_shield'] = function divineShieldScript(world, actor, spell, _intent) {
  const pos = /** @type any */ (world.get(actor, Position));
  if (!pos) return;
  const ae = ensureActiveEffectList(world, actor);
  if (!ae) return;

  const active = spell?.activeEffect || {};
  const DURATION = Math.max(1, Number(active.duration || 20) | 0);
  upsertTimedEffect(ae.effects, {
    key: spell?.id || 'divine_shield',
    turnsLeft: DURATION,
    potency: Number(active.potency ?? 1),
    stacks: Number(active.stacks ?? 1),
    sourceId: actor,
    meta: { ...(active.mechanics || {}) },
  });

  world.emit('spell:divine_shield', { actor, at: { x: pos.x, y: pos.y }, duration: DURATION });
};

REGISTRY['consecrate'] = function consecrateScript(world, actor, spell, _intent) {
  const apos = /** @type any */ (world.get(actor, Position));
  if (!apos) return;

  const RADIUS = Number(spell?.radius || 2) | 0;
  const active = spell?.activeEffect || {};
  const mechanics = active.mechanics || {};
  const TURNS = Math.max(1, Number(mechanics.hazardDuration ?? active.duration ?? 5) | 0);
  const BASE_TICK = 3;
  const scaledDmg = scaleSpellDamage(world, actor, BASE_TICK);

  // Holy ground hazard — damages hostiles
  spawnHazard(world, {
    x: apos.x,
    y: apos.y,
    kind: 'holy',
    medium: 'floor',
    turnsLeft: TURNS,
    radius: RADIUS,
    tickDamage: scaledDmg,
    damageType: 'holy',
    cause: 'spell:consecrate',
    sourceId: actor,
    sourceKind: 'consecrate',
    identity: 'consecrate_ground',
    name: 'Consecrated Ground',
    meta: { casterOnly: true },
  });

  // Caster recovery is owned by the spell identity; the ground field remains
  // an independent hazard because it has its own position and lifecycle.
  const ae = ensureActiveEffectList(world, actor);
  if (ae) {
    upsertTimedEffect(ae.effects, {
      key: spell?.id || 'consecrate',
      turnsLeft: Math.max(1, Number(active.duration || 5) | 0),
      potency: Number(active.potency ?? 1),
      stacks: Number(active.stacks ?? 1),
      sourceId: actor,
      meta: {
        ...(active.mechanics || {}),
        spellHealing: createSpellDamageContext(world, actor, spell, { cause: 'consecrate:recovery', type: 'healing' }),
      },
    });
  }

  world.emit('spell:consecrate', {
    actor,
    at: { x: apos.x, y: apos.y },
    radius: RADIUS,
  });
};

