  assertEquals(calls[1]?.type, "start");
  assertEquals(calls[1]?.url, "./assets/audio/ambient:holy_site.mp3");
  assertEquals(calls[1]?.opts?.bus, "ambient:loop");
  assertEquals(calls[2]?.type, "start");
